package net.civeira.phylax.features.access.userconsentedscopes.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class GrantedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property granted of user consented scopes ")
  void test_granted_v_o_builder() {
    Assertions.assertFalse(GrantedVO.nullValue().isGranted(),
        "A empty vo should have a null value");
    Assertions.assertFalse(GrantedVO.tryFrom(null).isGranted(),
        "With a null value, no present result");
    Assertions.assertEquals(true, GrantedVO.from(true).isGranted());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> GrantedVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", GrantedVO.from(true).toString());
  }
}
